<?php

declare(strict_types=1);
require_once __DIR__.'/CompanyTaskTimeBatchSchema.php';
/** One mutex, two native timer namespaces; all billing profiles share these vetoes. */
final class CompanyTaskTimeBatchFence
{
 public static function tables($db,string $p):array{$names=array_keys(CompanyTaskTimeBatchSchema::definitions());$present=false;foreach($names as $t)$present=$present||$db->table_exists($p.$t);if(!$present)return [];CompanyTaskTimeBatchSchema::assertValid($db,$p);return array_merge(['issuers_lock','company_projects','company_tasks','company_task_timers','company_standalone_tasks','company_standalone_timers','company_invoice_requests'],$names);}
 private static function claims($db,string $p,string $kind,int $issuer,int $task):array{$tables=self::tables($db,$p);if(!$tables)return [];IssuerTransaction::assertOwned($db,$p,$tables);$table=match($kind){'projects'=>'company_task_time_batch_claims','standalone'=>'company_standalone_time_claims',default=>throw new DomainException('company_time_batch_invalid')};$rows=IssuerStorage::query($db,'SELECT timer_id,origin_id,state FROM '.$p.$table.' WHERE issuer_id=? AND task_id=? ORDER BY timer_id FOR UPDATE',[$issuer,$task])->result_array();foreach($rows as $r)if(!in_array($r['state'],['converting','converted'],true))throw new RuntimeException('issuer_time_batch_unconfirmed');return $rows;}
 public static function stateInOwned($db,string $p,string $kind,int $issuer,int $task):?string{$rows=self::claims($db,$p,$kind,$issuer,$task);if(!$rows)return null;foreach($rows as $r)if($r['state']==='converting')return 'converting';return 'partially_billed';}
 public static function assertMutableInOwned($db,string $p,string $kind,int $issuer,int $task):void{if(self::stateInOwned($db,$p,$kind,$issuer,$task)==='converting')throw new DomainException('company_time_batch_immutable');}
 public static function assertWholeInOwned($db,string $p,string $kind,int $issuer,int $task):void{if(self::stateInOwned($db,$p,$kind,$issuer,$task)!==null)throw new DomainException('company_time_batch_overlap');}
 public static function assertProjectInOwned($db,string $p,int $issuer,int $project,bool $pendingOnly=false):void{$t=self::tables($db,$p);if(!$t)return;IssuerTransaction::assertOwned($db,$p,$t);$rows=IssuerStorage::query($db,'SELECT origin_id FROM '.$p.'company_task_time_batch_claims WHERE issuer_id=? AND project_id=?'.($pendingOnly?' AND state=?':'').' LIMIT 1 FOR UPDATE',$pendingOnly?[$issuer,$project,'converting']:[$issuer,$project])->result_array();if($rows)throw new DomainException($pendingOnly?'company_time_batch_immutable':'company_time_batch_overlap');}
 public static function assertSelectionInOwned($db,string $p,string $kind,int $issuer,array $timerIds,int $ownOrigin=0,bool $checkPending=true):void{$t=self::tables($db,$p);if(!$t)return;IssuerTransaction::assertOwned($db,$p,$t);if(!$timerIds)throw new DomainException('company_time_batch_invalid');$native=match($kind){'projects'=>'company_task_timers','standalone'=>'company_standalone_timers',default=>throw new DomainException('company_time_batch_invalid')};$claims=match($kind){'projects'=>'company_task_time_batch_claims','standalone'=>'company_standalone_time_claims',default=>throw new DomainException('company_time_batch_invalid')};$q=implode(',',array_fill(0,count($timerIds),'?'));$rows=IssuerStorage::query($db,'SELECT id,task_id FROM '.$p.$native.' WHERE issuer_id=? AND id IN('.$q.') ORDER BY id FOR UPDATE',array_merge([$issuer],$timerIds))->result_array();if(array_map(fn($r)=>(int)$r['id'],$rows)!==$timerIds)throw new DomainException('company_time_batch_denied');foreach($rows as $row){$claim=IssuerStorage::query($db,'SELECT issuer_id,origin_id,state FROM '.$p.$claims.' WHERE timer_id=? FOR UPDATE',[$row['id']])->row_array();if($claim&&((int)$claim['issuer_id']!==$issuer||(int)$claim['origin_id']!==$ownOrigin))throw new DomainException('company_time_batch_overlap');if($checkPending)foreach(self::claims($db,$p,$kind,$issuer,(int)$row['task_id']) as $other)if($other['state']==='converting'&&(int)$other['origin_id']!==$ownOrigin)throw new DomainException('company_time_batch_immutable');}}
 public static function allocationInOwned($db,string $p,string $kind,int $issuer,int $timer):?array{$t=self::tables($db,$p);if(!$t)return null;IssuerTransaction::assertOwned($db,$p,$t);$table=match($kind){'projects'=>'company_task_time_batch_claims','standalone'=>'company_standalone_time_claims',default=>throw new DomainException('company_time_batch_invalid')};$r=IssuerStorage::query($db,'SELECT issuer_id,origin_id,state FROM '.$p.$table.' WHERE timer_id=? FOR UPDATE',[$timer])->row_array();if(!$r)return null;if((int)$r['issuer_id']!==$issuer||!in_array($r['state'],['converting','converted'],true))throw new RuntimeException('issuer_time_batch_unconfirmed');return$r;}
 public static function key(int $issuer,int $origin):string{return hash('sha256','company-task-time-multi-batch-invoice:'.$issuer.':'.$origin);}
}
